package com.tihai.controller;
import com.tihai.utils.*;import com.tihai.common.R;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import org.springframework.test.util.ReflectionTestUtils;import java.util.*;import java.util.concurrent.*;import java.nio.file.*;import java.io.*;import static org.junit.jupiter.api.Assertions.*;
class RainControllerTest {
 @TempDir Path root;@AfterEach void clear()throws Exception{AccountScope.clear();WindowsTestCleanup.remove(root);}
 static class Bridge implements ExamBrowserSession {BlockingQueue<Map<String,Object>> q=new LinkedBlockingQueue<>();List<Map<String,Object>> commands=new CopyOnWriteArrayList<>();String account;public void send(Map<String,Object> c){commands.add(new LinkedHashMap<>(c));Map<String,Object> response=new LinkedHashMap<>();response.put("event","response");response.put("requestId",c.get("requestId"));response.put("ok",true);Map data=new LinkedHashMap();if("confirm".equals(c.get("op"))){data.put("loggedIn",true);data.put("identity",account);}response.put("data",data);q.add(response);}public Map<String,Object> read()throws IOException{try{return q.take();}catch(InterruptedException e){throw new IOException(e);}}public void close(){}}
 class Fixture extends RainController implements AutoCloseable {final AccountRegistry registryValue=new AccountRegistry(root);final RainStore storeValue=new RainStore(root);final Map<String,Bridge> bridges=new HashMap<>();String a,b;Fixture()throws Exception{a=String.valueOf(registryValue.addRain("Fixture A","https://www.yuketang.cn/").get("id"));b=String.valueOf(registryValue.addRain("Fixture B","https://www.yuketang.cn/").get("id"));ReflectionTestUtils.setField(this,"registry",registryValue);ReflectionTestUtils.setField(this,"store",storeValue);ReflectionTestUtils.setField(this,"review",new ReviewStore(root.resolve("library.json")));ReflectionTestUtils.setField(this,"security",new SecurityAlertHub());choose(a);}@Override protected ExamBrowserSession open(String a){Bridge bridge=new Bridge();bridge.account=a;bridges.put(a,bridge);return bridge;}void choose(String id){AccountScope.bind(registryValue.lookup(id));}String task()throws Exception{Map<String,String> b=new LinkedHashMap<>();b.put("title","Fixture course");b.put("url","https://www.yuketang.cn/v2/web/studentLog/123");b.put("module","chapters");R r=addTask(b);assertEquals(200,r.get("code"));return String.valueOf(((Map)r.get("data")).get("id"));}void loginNow(){assertEquals(200,login().get("code"));assertEquals(200,confirm().get("code"));}Map<String,Object> startBody(String id){Map<String,Object> b=new HashMap<>();b.put("id",id);return b;}public void close(){super.close();}}
 @Test void addingTaskDoesNotOpenBrowserOrStartAnything()throws Exception{try(Fixture f=new Fixture()){String id=f.task();assertTrue(f.bridges.isEmpty());assertEquals("stopped",f.storeValue.task(id,f.a).get("state"));assertEquals(false,f.storeValue.task(id,f.a).get("autoSubmit"));}}
 @Test void startRequiresVerifiedLoginAndOptionsDefaultOff()throws Exception{try(Fixture f=new Fixture()){String id=f.task();assertNotEquals(200,f.start(f.startBody(id)).get("code"));assertTrue(f.bridges.isEmpty());f.loginNow();assertEquals(200,f.start(f.startBody(id)).get("code"));Map cmd=f.bridges.get(f.a).commands.stream().filter(c->"start".equals(c.get("op"))).findFirst().get();assertEquals(false,cmd.get("autoAI"));assertEquals(false,cmd.get("autoSubmit"));assertEquals(200,f.stop(Collections.singletonMap("id",id)).get("code"));}}
 @Test void accountSwitchHidesOtherTasksAndCannotStopOrDeleteThem()throws Exception{try(Fixture f=new Fixture()){String id=f.task();f.loginNow();f.start(f.startBody(id));f.choose(f.b);assertTrue(((List)((Map)f.list("chapters").get("data")).get("items")).isEmpty());assertNotEquals(200,f.stop(Collections.singletonMap("id",id)).get("code"));assertNotEquals(200,f.delete(Collections.singletonMap("id",id)).get("code"));assertEquals("starting",f.storeValue.task(id,f.a).get("state"));f.choose(f.a);assertEquals(200,f.stop(Collections.singletonMap("id",id)).get("code"));assertEquals(200,f.delete(Collections.singletonMap("id",id)).get("code"));}}
 @Test void automaticSubmissionRequiresExplicitConfirmationAndCannotRunSecondTaskInSameProfile()throws Exception{try(Fixture f=new Fixture()){String id=f.task();f.loginNow();Map<String,Object> b=f.startBody(id);b.put("autoSubmit",true);assertNotEquals(200,f.start(b).get("code"));b.put("confirmed",true);assertEquals(200,f.start(b).get("code"));assertNotEquals(200,f.start(b).get("code"));assertEquals(1,f.bridges.get(f.a).commands.stream().filter(c->"start".equals(c.get("op"))).count());}}
}
